<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>@yield('title','CRM ЗЦРБ')</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.sidebar{width:260px;min-height:100vh;background:#fff;border-right:1px solid #e7ebef}.sidebar a{color:#344054;text-decoration:none}.sidebar .nav-link.active,.sidebar .nav-link:hover{background:#eef6ff;color:#0d6efd}.content{min-width:0}.stat-card{border:0;box-shadow:0 1px 3px rgba(16,24,40,.08)}.task-overdue{border-left:4px solid #dc3545}.navbar-brand{font-weight:600}.notification-menu{width:min(420px,92vw);max-height:520px;overflow:auto}.notification-item{white-space:normal}.notification-item.unread{background:#f0f7ff}.notification-dot{width:8px;height:8px;border-radius:50%;background:#0d6efd;flex:0 0 8px}</style>@stack('styles')</head>
<body><div class="d-flex"><aside class="sidebar p-3 d-none d-lg-block"><div class="fw-bold fs-5 mb-4"><i class="bi bi-hospital me-2 text-primary"></i>CRM ЗЦРБ</div><nav class="nav flex-column gap-1"><a class="nav-link rounded {{ request()->routeIs('dashboard')?'active':'' }}" href="{{ route('dashboard') }}"><i class="bi bi-speedometer2 me-2"></i>Главная</a><a class="nav-link rounded {{ request()->routeIs('tasks.*')?'active':'' }}" href="{{ route('tasks.page') }}"><i class="bi bi-check2-square me-2"></i>Задачи</a><a class="nav-link rounded {{ request()->routeIs('plans.*')?'active':'' }}" href="{{ route('plans.page') }}"><i class="bi bi-calendar3 me-2"></i>Планы</a><a class="nav-link rounded {{ request()->routeIs('calendar.*')?'active':'' }}" href="{{ route('calendar.page') }}"><i class="bi bi-calendar-week me-2"></i>Календарь</a><a class="nav-link rounded {{ request()->routeIs('employees.*')?'active':'' }}" href="{{ route('employees.page') }}"><i class="bi bi-people me-2"></i>Сотрудники</a><a class="nav-link rounded {{ request()->routeIs('departments.*')?'active':'' }}" href="{{ route('departments.page') }}"><i class="bi bi-diagram-3 me-2"></i>Подразделения</a>@if(auth()->user()->isManager())<a class="nav-link rounded {{ request()->routeIs('control.*')?'active':'' }}" href="{{ route('control.page') }}"><i class="bi bi-bar-chart me-2"></i>Контроль</a>@endif</nav></aside><main class="content flex-grow-1"><nav class="navbar bg-white border-bottom px-4"><span class="navbar-brand mb-0 h1">@yield('header','CRM ЗЦРБ')</span><div class="ms-auto d-flex align-items-center gap-3"><div class="dropdown"><button class="btn btn-sm btn-light border position-relative" id="notificationButton" data-bs-toggle="dropdown" aria-expanded="false" title="Уведомления"><i class="bi bi-bell fs-5"></i><span id="notificationBadge" class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger d-none">0</span></button><div class="dropdown-menu dropdown-menu-end p-0 notification-menu"><div class="d-flex justify-content-between align-items-center px-3 py-2 border-bottom"><strong>Уведомления</strong><button class="btn btn-sm btn-link text-decoration-none" onclick="markAllNotificationsRead()">Прочитать все</button></div><div id="notificationList"><div class="text-center text-muted py-4">Загрузка...</div></div></div></div><span>{{ auth()->user()->full_name ?? '' }}</span><form method="POST" action="{{ route('logout') }}">@csrf<button class="btn btn-sm btn-outline-secondary" title="Выйти"><i class="bi bi-box-arrow-right"></i></button></form></div></nav><div class="container-fluid p-4">@yield('content')</div></main></div><script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>$.ajaxSetup({headers:{'X-CSRF-TOKEN':$('meta[name="csrf-token"]').attr('content')}});function escNotification(v){return $('<div>').text(v??'').html()}function notificationIcon(type){return {task_assigned:'bi-check2-square',task_review:'bi-clipboard-check',task_accepted:'bi-check-circle',task_rejected:'bi-arrow-counterclockwise',task_comment:'bi-chat-left-text',task_due_soon:'bi-alarm',task_overdue:'bi-exclamation-triangle'}[type]||'bi-bell'}function loadNotifications(){$.get('{{ route('notifications.index') }}',function(r){const n=r.unread||0;$('#notificationBadge').text(n>99?'99+':n).toggleClass('d-none',n===0);let h='';(r.items||[]).forEach(x=>{h+=`<a href="#" class="dropdown-item notification-item border-bottom py-3 ${x.read_at?'':'unread'}" onclick="openNotification(event,${x.id},'${escNotification(x.url||'')}')"><div class="d-flex gap-2"><div class="pt-1">${x.read_at?'':`<div class="notification-dot"></div>`}</div><div class="flex-grow-1"><div class="fw-semibold"><i class="bi ${notificationIcon(x.type)} me-1"></i>${escNotification(x.title)}</div><div class="small text-muted mt-1">${escNotification(x.body||'')}</div><div class="small text-secondary mt-1">${new Date(x.created_at).toLocaleString('ru-RU')}</div></div></div></a>`});$('#notificationList').html(h||'<div class="text-center text-muted py-4">Новых событий нет</div>')})}function openNotification(e,id,url){e.preventDefault();$.post(`{{ url('/ajax/notifications') }}/${id}/read`).always(()=>{if(url)window.location.href=url;else loadNotifications()})}function markAllNotificationsRead(){$.post('{{ route('notifications.read-all') }}').done(loadNotifications)}$('#notificationButton').on('click',loadNotifications);loadNotifications();setInterval(loadNotifications,60000);</script>@stack('scripts')</body></html>
